add_action( 'pre_get_posts', 'perfectpixel_category_sticky_exclude' );
add_filter( 'the_posts', 'perfectpixel_category_sticky_prepend', 10, 2 );
add_filter( 'post_class', 'perfectpixel_category_sticky_class', 10, 3 );

function perfectpixel_category_sticky_ids() {
	return array_filter( array_map( 'absint', (array) get_option( 'sticky_posts', array() ) ) );
}

// Keep sticky posts out of the normal list so they are not repeated on later pages.
function perfectpixel_category_sticky_exclude( $query ) {
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_category() || ! perfectpixel_category_sticky_ids() ) {
		return;
	}
	$query->set( 'post__not_in', array_merge( (array) $query->get( 'post__not_in' ), perfectpixel_category_sticky_ids() ) );
}

function perfectpixel_category_sticky_prepend( $posts, $query ) {
	if ( is_admin() || ! $query->is_main_query() || ! $query->is_category() || $query->get( 'paged' ) > 1 ) {
		return $posts;
	}
	$ids = perfectpixel_category_sticky_ids();
	if ( ! $ids ) {
		return $posts;
	}
	$sticky = get_posts(
		array(
			'post__in'            => $ids,
			'cat'                 => (int) $query->get_queried_object_id(),
			'posts_per_page'      => count( $ids ),
			'ignore_sticky_posts' => true,
			'orderby'             => 'date',
			'order'               => 'DESC',
		)
	);
	return $sticky ? array_merge( $sticky, (array) $posts ) : $posts;
}

function perfectpixel_category_sticky_class( $classes, $css_class, $post_id ) {
	if ( is_category() && ! is_admin() && is_sticky( $post_id ) && ! in_array( 'sticky', $classes, true ) ) {
		$classes[] = 'sticky';
	}
	return $classes;
}
